contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // run takes a single deposit amount and then calls withdrawAll once.
    function run(uint depositAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmount)); require(depositAmount <= 1000000000000000000000000000000);
        require(address(this).balance >= depositAmount);

        // observe contract-level balance before any action
        uint beforeC = address(c).balance;
        // observe recorded credit for this contract before any action via depositing zero to read mapping? There is no getter; but credit is private in C so we cannot read it. Instead we reason about the observable sum: address(c).balance + recorded credit (pre-deposit) can't be read directly. However, after deposit we can observe address(c).balance and after withdraw we can observe address(c).balance again and whether this contract received funds by checking address(this).balance.
        // Make a deposit of depositAmount
        c.deposit{value: depositAmount}(); if (__ESBMC_reverted()) return;

        // Record observable quantities immediately after deposit
        uint afterDeposit_cBal = address(c).balance;
        uint afterDeposit_selfBal = address(this).balance;

        // attempt withdrawAll and catch revert
        bool reverted;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // Record observable quantities after withdrawAll (or its revert)
        uint afterCall_cBal = address(c).balance;
        uint afterCall_selfBal = address(this).balance;

        // General invariant: the sum (afterCall_cBal + afterCall_selfBal) is <= (afterDeposit_cBal + afterDeposit_selfBal)
        // i.e., withdrawAll cannot increase the total observable ether between C and this test contract compared to immediately after deposit
        assert(afterCall_cBal + afterCall_selfBal <= afterDeposit_cBal + afterDeposit_selfBal);
    }

    receive() external payable { }
}

